import timeit, importlib.metadata as md
from tabulate import tabulate
import prettytable, texttable
headers = ['col%d' % i for i in range(10)]
table = [['some text'] + list(range(i, i + 9)) for i in range(10)]  # 10x10 mixed text/numeric, as in benchmark/benchmark.py
def run_tabulate():
    return tabulate(table, headers)
def run_prettytable():
    pt = prettytable.PrettyTable(headers)
    for r in table:
        pt.add_row(r)
    return pt.get_string()
def run_texttable():
    tt = texttable.Texttable()
    tt.add_rows([headers] + table)
    return tt.draw()
N = 2000
res = {}
for name, fn in [('tabulate', run_tabulate), ('prettytable', run_prettytable), ('texttable', run_texttable)]:
    fn()
    best = min(timeit.repeat(fn, number=N, repeat=3)) / N * 1e6
    res[name] = best
    print('observed: %-12s %-8s %8.1f us/call' % (name, md.version(name), best))
faster_tt = res['tabulate'] < res['texttable']
faster_pt = res['tabulate'] < res['prettytable']
